import heapq
from typing import List

def minTimeToReach(moveTime: List[List[int]]) -> int:
    n = len(moveTime)
    m = len(moveTime[0])

    # Priority queue for Dijkstra's algorithm: (current_time, r, c)
    pq = [(0, 0, 0)]
    # Distance matrix to store minimum time to reach each cell
    dist = [[float('inf')] * m for _ in range(n)]
    dist[0][0] = 0

    while pq:
        curr_t, r, c = heapq.heappop(pq)

        if curr_t > dist[r][c]:
            continue

        if r == n - 1 and c == m - 1:
            return int(curr_t)

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                # The problem states moveTime[i][j] is the minimum time you can START moving to that room.
                # To enter a neighbor from (r, c), we must arrive at it at max(curr_t + 1, moveTime[nr][nc]).
                # However, if curr_t + 1 < moveTime[nr][nc], we wait until moveTime[nr][nc] and then spend 1 second to enter.
                # The actual arrival time is max(curr_t + 1, moveTime[nr][nc] + 1).

                arrival_time = max(curr_t + 1, moveTime[nr][nc] + 1)
                if arrival_time < dist[nr][nc]:
                    dist[nr][nc] = arrival_time
                    heapq.heappush(pq, (arrival_time, nr, nc))

    return int(dist[n-1][m-1])
