            if not is_blocked and 0 < c < n:
                valid_candidates.append(c)

        if len(valid_candidates) < 2:
            return False

        # To have three non-empty sections, we need p1 < p2 such that:
        # 1. At least one rect has e <= p1 (Section 1)
        # 2. At least one rect has s >= p1 and e <= p2 (Section 2)
        # 3. At least one rect has s >= p2 (Section 3)

