            if s > 0 and s < n:
                idx = bisect.bisect_right(valid_candidates, s) - 1
                if idx >= 0:
                    best_p2 = max(best_p2, valid_candidates[idx])

        if best_p1 == float('inf') or best_p2 == float('-inf') or best_p1 >= best_p2:
            return False

        # Check if there is a rectangle that can serve as the "middle" section.
        # It must be strictly between p1 and p2 to ensure it's not part of section 1 or 3.
        # Actually, because they don't overlap, we just need any rect i such that:
        # e_j <= best_p1 (some j), s_i >= best_p1 and e_i <= best_p2 (some i), s_k >= best_p2 (some k).
