    row_data = []
    for r in range(rows):
        unique_in_row = sorted(list(set(grid[r])), reverse=True)
        row_data.append(unique_in_row)

    @lru_cache(None)
    def solve(row_idx: int, used_mask: int) -> int:
        if row_idx == rows:
            return 0

        # Option 1: Don't pick any cell from this row
        res = solve(row_idx + 1, used_mask)

        # Option 2: Pick one cell from this row
        for val in row_data[row_idx]:
            # We need to map the actual value to a bit position.
            # Since values are small (1-100), we can use the value itself as bit index.
            if not (used_mask & (1 << val)):
                res = max(res, val + solve(row_idx + 1, used_mask | (1 << val)))

        return res

    # To optimize memory/speed since values are up to 100 but we only care about values present in grid
    unique_vals = sorted(list(set(val for row in grid for val in row)))
    val_to_idx = {v: i for i, v in enumerate(unique_vals)}

    # Re-mapping to small indices for the bitmask
    mapped_row_data = []
    for r in range(rows):
        mapped_row_data.append([val_to_idx[v] for v in row_data[r]])

    @lru_cache(None)
    def solve_mapped(row_idx: int, used_mask: int) -> int:
        if row_idx == rows:
            return 0

        res = solve_mapped(row_idx + 1, used_mask)

        for val_idx in mapped_row_data[row_idx]:
            val = unique_vals[val_idx]
            if not (used_mask & (1 << val_idx)):
                res = max(res, val + solve_mapped(row_idx + 1, used_mask | (1 << val_idx)))
        return res

    return solve_mapped(0, 0)
