from typing import List

def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # Convert each row to a set of unique integers for fast intersection counting
    sets = [set(p) for p in properties]
    adj = [[] for _ in range(n)]

    # Build adjacency list
    for i in range(n):
        for j in range(i + 1, n):
            if len(sets[i] & sets[j]) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    count = 0
    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
    return count
